# Inequality: 3(a_i^2 + a_j^2) + 15a_i^2 a_j^2 >= (4a_ia_j + 1)^2
# Set A = {0.1, 1, 5}

def check_inequality(ai, aj):
    lhs = 3 * (ai**2 + aj**2) + 15 * (ai**2) * (aj**2)
    rhs = (4 * ai * aj + 1)**2
    return lhs >= rhs

# Pairs to check: (0.1, 1), (0.1, 5), (1, 5)
pairs = [(0.1, 1), (0.1, 5), (1, 5)]
results = {}

for ai, aj in pairs:
    is_satisfied = check_inequality(ai, aj)
    results[f"({ai}, {aj})"] = is_satisfied

print("Verification Results:")
for pair, satisfied in results.items():
    print(f"{pair}: {satisfied}")
